using UnityEngine;

namespace Metagame.Gameplay
{
    /// <summary>
    /// Marks a collider generated by an editor layout builder. Authored art colliders
    /// intentionally do not receive this component and are preserved on rebuild.
    /// </summary>
    public sealed class Stage1GeneratedCollider : MonoBehaviour
    {
        [SerializeField] bool removeOwnerOnCleanup;

        /// <summary>
        /// Compound fallback colliders live on generated child objects, while mesh
        /// colliders live on the art's MeshFilter object. Builders set this flag only
        /// for the former so cleanup removes the generated child without deleting art.
        /// </summary>
        public bool RemoveOwnerOnCleanup
        {
            get => removeOwnerOnCleanup;
            set => removeOwnerOnCleanup = value;
        }
    }
}
